add_action( 'template_redirect', 'perfectpixel_single_product_category_redirect' );

function perfectpixel_single_product_category_redirect() {
	global $wp_query;
	if ( ! function_exists( 'is_product_category' ) || ! is_product_category() || is_paged() || ! empty( $_GET ) ) {
		return;
	}
	$only = wp_parse_id_list( '{{single_cat_redirect_ids}}' );
	if ( $only && ! in_array( get_queried_object_id(), $only, true ) ) {
		return;
	}
	if ( 1 === (int) $wp_query->found_posts && ! empty( $wp_query->posts[0] ) ) {
		wp_safe_redirect( get_permalink( $wp_query->posts[0] ) );
		exit;
	}
}
